<?php
namespace App\Filament\Admin\Resources\FinancialCases;use App\Domain\Tenancy\TenantContext;use App\Filament\Admin\Resources\FinancialCases\Pages;use App\Models\Chargeback;use BackedEnum;use Filament\Actions;use Filament\Resources\Resource;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables;use Filament\Tables\Table;use Illuminate\Database\Eloquent\Builder;
final class FinancialCaseResource extends Resource{protected static?string$model=Chargeback::class;protected static string|BackedEnum|null$navigationIcon=Heroicon::OutlinedExclamationTriangle;protected static string|\UnitEnum|null$navigationGroup='Financial operations';protected static?int$navigationSort=64;public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->where('tenant_id',app(TenantContext::class)->id());}public static function form(Schema$s):Schema{return$s->components([]);}public static function table(Table$t):Table{return$t->columns([Tables\Columns\TextColumn::make('provider_case_reference')->label('Provider case')->searchable(),Tables\Columns\TextColumn::make('amount_minor')->money(fn($record)=>$record->currency,divideBy:100),Tables\Columns\TextColumn::make('reason_code')->badge(),Tables\Columns\TextColumn::make('response_due_at')->dateTime(),Tables\Columns\TextColumn::make('status')->badge()->color(fn(string$state)=>match($state){'WON'=>'success','LOST'=>'danger','OPEN','UNDER_REVIEW'=>'warning',default=>'gray'})])->recordActions([Actions\ViewAction::make()]);}public static function getPages():array{return['index'=>Pages\ListFinancialCases::route('/'),'view'=>Pages\ViewFinancialCase::route('/{record}')];}}
